     1→import {BitArray} from "@chainsafe/ssz";
     2→import {routes} from "@lodestar/api";
     3→import {
     4→  AncestorStatus,
     5→  EpochDifference,
     6→  ForkChoiceError,
     7→  ForkChoiceErrorCode,
     8→  NotReorgedReason,
     9→} from "@lodestar/fork-choice";
    10→import {ForkPostAltair, ForkPostElectra, ForkSeq, MAX_SEED_LOOKAHEAD, SLOTS_PER_EPOCH} from "@lodestar/params";
    11→import {
    12→  CachedBeaconStateAltair,
    13→  EpochCache,
    14→  RootCache,
    15→  computeEpochAtSlot,
    16→  computeStartSlotAtEpoch,
    17→  computeTimeAtSlot,
    18→  isExecutionStateType,
    19→  isStartSlotOfEpoch,
    20→  isStateValidatorsNodesPopulated,
    21→} from "@lodestar/state-transition";
    22→import {Attestation, BeaconBlock, altair, capella, electra, phase0, ssz} from "@lodestar/types";
    23→import {isErrorAborted, toRootHex} from "@lodestar/utils";
    24→import {ZERO_HASH_HEX} from "../../constants/index.js";
    25→import {callInNextEventLoop} from "../../util/eventLoop.js";
    26→import {isOptimisticBlock} from "../../util/forkChoice.js";
    27→import {isQueueErrorAborted} from "../../util/queue/index.js";
    28→import type {BeaconChain} from "../chain.js";
    29→import {ChainEvent, ReorgEventData} from "../emitter.js";
    30→import {ForkchoiceCaller} from "../forkChoice/index.js";
    31→import {REPROCESS_MIN_TIME_TO_NEXT_SLOT_SEC} from "../reprocess.js";
    32→import {toCheckpointHex} from "../stateCache/index.js";
    33→import {isBlockInputBlobs, isBlockInputColumns} from "./blockInput/blockInput.js";
    34→import {AttestationImportOpt, FullyVerifiedBlock, ImportBlockOpts} from "./types.js";
    35→import {getCheckpointFromState} from "./utils/checkpoint.js";
    36→import {writeBlockInputToDb} from "./writeBlockInputToDb.js";
    37→
    38→/**
    39→ * Fork-choice allows to import attestations from current (0) or past (1) epoch.
    40→ */
    41→const FORK_CHOICE_ATT_EPOCH_LIMIT = 1;
    42→/**
    43→ * Emit eventstream events for block contents events only for blocks that are recent enough to clock
    44→ */
    45→const EVENTSTREAM_EMIT_RECENT_BLOCK_SLOTS = 64;
    46→
    47→/**
    48→ * Imports a fully verified block into the chain state. Produces multiple permanent side-effects.
    49→ *
    50→ * ImportBlock order of operations must guarantee that BeaconNode does not end in an unknown state:
    51→ *
    52→ * 1. Persist block to hot DB (pre-emptively)
    53→ *    - Done before importing block to fork-choice to guarantee that blocks in the fork-choice *always* are persisted
    54→ *      in the DB. Otherwise the beacon node may end up in an unrecoverable state. If a block is persisted in the hot
    55→ *      db but is unknown by the fork-choice, then it will just use some extra disk space. On restart is will be
    56→ *      pruned regardless.
    57→ *    - Note that doing a disk write first introduces a small delay before setting the head. An improvement where disk
    58→ *      write happens latter requires the ability to roll back a fork-choice head change if disk write fails
    59→ *
    60→ * 2. Import block to fork-choice
    61→ * 3. Import attestations to fork-choice
    62→ * 4. Import attester slashings to fork-choice
    63→ * 5. Compute head. If new head, immediately stateCache.setHeadState()
    64→ * 6. Queue notifyForkchoiceUpdate to engine api
    65→ * 7. Add post state to stateCache
    66→ */
    67→export async function importBlock(
    68→  this: BeaconChain,
    69→  fullyVerifiedBlock: FullyVerifiedBlock,
    70→  opts: ImportBlockOpts
    71→): Promise<void> {
    72→  const {blockInput, postState, parentBlockSlot, executionStatus, dataAvailabilityStatus} = fullyVerifiedBlock;
    73→  const block = blockInput.getBlock();
    74→  const source = blockInput.getBlockSource();
    75→  const {slot: blockSlot} = block.message;
    76→  const blockRoot = this.config.getForkTypes(blockSlot).BeaconBlock.hashTreeRoot(block.message);
    77→  const blockRootHex = toRootHex(blockRoot);
    78→  const currentSlot = this.forkChoice.getTime();
    79→  const currentEpoch = computeEpochAtSlot(currentSlot);
    80→  const blockEpoch = computeEpochAtSlot(blockSlot);
    81→  const prevFinalizedEpoch = this.forkChoice.getFinalizedCheckpoint().epoch;
    82→  const blockDelaySec =
    83→    fullyVerifiedBlock.seenTimestampSec - computeTimeAtSlot(this.config, blockSlot, postState.genesisTime);
    84→  const recvToValLatency = Date.now() / 1000 - (opts.seenTimestampSec ?? Date.now() / 1000);
    85→  const fork = this.config.getForkSeq(blockSlot);
    86→
    87→  // this is just a type assertion since blockinput with dataPromise type will not end up here
    88→  if (!blockInput.hasAllData) {
    89→    throw Error("Unavailable block can not be imported in forkchoice");
    90→  }
    91→
    92→  // 1. Persist block to hot DB (pre-emptively)
    93→  // If eagerPersistBlock = true we do that in verifyBlocksInEpoch to batch all I/O operations to save block time to head
    94→  if (!opts.eagerPersistBlock) {
    95→    await writeBlockInputToDb.call(this, [blockInput]);
    96→  }
    97→
    98→  // 2. Import block to fork choice
    99→
   100→  // Should compute checkpoint balances before forkchoice.onBlock
   101→  this.checkpointBalancesCache.processState(blockRootHex, postState);
   102→  const blockSummary = this.forkChoice.onBlock(
   103→    block.message,
   104→    postState,
   105→    blockDelaySec,
   106→    currentSlot,
   107→    executionStatus,
   108→    dataAvailabilityStatus
   109→  );
   110→
   111→  // This adds the state necessary to process the next block
   112→  // Some block event handlers require state being in state cache so need to do this before emitting EventType.block
   113→  this.regen.processState(blockRootHex, postState);
   114→
   115→  this.metrics?.importBlock.bySource.inc({source: source.source});
   116→  this.logger.verbose("Added block to forkchoice and state cache", {slot: blockSlot, root: blockRootHex});
   117→
   118→  // 3. Import attestations to fork choice
   119→  //
   120→  // - For each attestation
   121→  //   - Get indexed attestation
   122→  //   - Register attestation with fork-choice
   123→  //   - Register attestation with validator monitor (only after sync)
   124→  // Only process attestations of blocks with relevant attestations for the fork-choice:
   125→  // If current epoch is N, and block is epoch X, block may include attestations for epoch X or X - 1.
   126→  // The latest block that is useful is at epoch N - 1 which may include attestations for epoch N - 1 or N - 2.
   127→  if (
   128→    opts.importAttestations === AttestationImportOpt.Force ||
   129→    (opts.importAttestations !== AttestationImportOpt.Skip && blockEpoch >= currentEpoch - FORK_CHOICE_ATT_EPOCH_LIMIT)
   130→  ) {
   131→    const attestations = block.message.body.attestations;
   132→    const rootCache = new RootCache(postState);
   133→    const invalidAttestationErrorsByCode = new Map<string, {error: Error; count: number}>();
   134→
   135→    const addAttestation = fork >= ForkSeq.electra ? addAttestationPostElectra : addAttestationPreElectra;
   136→
   137→    for (const attestation of attestations) {
   138→      try {
   139→        // TODO Electra: figure out how to reuse the attesting indices computed from state transition
   140→        const indexedAttestation = postState.epochCtx.getIndexedAttestation(fork, attestation);
   141→        const {target, beaconBlockRoot} = attestation.data;
   142→
   143→        const attDataRoot = toRootHex(ssz.phase0.AttestationData.hashTreeRoot(indexedAttestation.data));
   144→        addAttestation.call(
   145→          this,
   146→          postState.epochCtx,
   147→          target,
   148→          attDataRoot,
   149→          attestation as Attestation<ForkPostElectra>,
   150→          indexedAttestation
   151→        );
   152→        // Duplicated logic from fork-choice onAttestation validation logic.
   153→        // Attestations outside of this range will be dropped as Errors, so no need to import
   154→        if (
   155→          opts.importAttestations === AttestationImportOpt.Force ||
   156→          (target.epoch <= currentEpoch && target.epoch >= currentEpoch - FORK_CHOICE_ATT_EPOCH_LIMIT)
   157→        ) {
   158→          this.forkChoice.onAttestation(
   159→            indexedAttestation,
   160→            attDataRoot,
   161→            opts.importAttestations === AttestationImportOpt.Force
   162→          );
   163→        }
   164→
   165→        // Note: To avoid slowing down sync, only register attestations within FORK_CHOICE_ATT_EPOCH_LIMIT
   166→        this.seenBlockAttesters.addIndices(blockEpoch, indexedAttestation.attestingIndices);
   167→
   168→        const correctHead = ssz.Root.equals(rootCache.getBlockRootAtSlot(attestation.data.slot), beaconBlockRoot);
   169→        const missedSlotVote = ssz.Root.equals(
   170→          rootCache.getBlockRootAtSlot(attestation.data.slot - 1),
   171→          rootCache.getBlockRootAtSlot(attestation.data.slot)
   172→        );
   173→        this.validatorMonitor?.registerAttestationInBlock(
   174→          indexedAttestation,
   175→          parentBlockSlot,
   176→          correctHead,
   177→          missedSlotVote,
   178→          blockRootHex,
   179→          blockSlot
   180→        );
   181→      } catch (e) {
   182→        // a block has a lot of attestations and it may has same error, we don't want to log all of them
   183→        if (e instanceof ForkChoiceError && e.type.code === ForkChoiceErrorCode.INVALID_ATTESTATION) {
   184→          let errWithCount = invalidAttestationErrorsByCode.get(e.type.err.code);
   185→          if (errWithCount === undefined) {
   186→            errWithCount = {error: e as Error, count: 1};
   187→            invalidAttestationErrorsByCode.set(e.type.err.code, errWithCount);
   188→          } else {
   189→            errWithCount.count++;
   190→          }
   191→        } else {
   192→          // always log other errors
   193→          this.logger.warn("Error processing attestation from block", {slot: blockSlot}, e as Error);
   194→        }
   195→      }
   196→    }
   197→
   198→    for (const {error, count} of invalidAttestationErrorsByCode.values()) {
   199→      this.logger.warn(
   200→        "Error processing attestations from block",
   201→        {slot: blockSlot, erroredAttestations: count},
   202→        error
   203→      );
   204→    }
   205→  }
   206→
   207→  // 4. Import attester slashings to fork choice
   208→  //
   209→  // FORK_CHOICE_ATT_EPOCH_LIMIT is for attestation to become valid
   210→  // but AttesterSlashing could be found before that time and still able to submit valid attestations
   211→  // until slashed validator become inactive, see computeActivationExitEpoch() function
   212→  if (
   213→    opts.importAttestations === AttestationImportOpt.Force ||
   214→    (opts.importAttestations !== AttestationImportOpt.Skip &&
   215→      blockEpoch >= currentEpoch - FORK_CHOICE_ATT_EPOCH_LIMIT - 1 - MAX_SEED_LOOKAHEAD)
   216→  ) {
   217→    for (const slashing of block.message.body.attesterSlashings) {
   218→      try {
   219→        // all AttesterSlashings are valid before reaching this
   220→        this.forkChoice.onAttesterSlashing(slashing);
   221→      } catch (e) {
   222→        this.logger.warn("Error processing AttesterSlashing from block", {slot: blockSlot}, e as Error);
   223→      }
   224→    }
   225→  }
   226→
   227→  // 5. Compute head. If new head, immediately stateCache.setHeadState()
   228→
   229→  const oldHead = this.forkChoice.getHead();
   230→  const newHead = this.recomputeForkChoiceHead(ForkchoiceCaller.importBlock);
   231→  const currFinalizedEpoch = this.forkChoice.getFinalizedCheckpoint().epoch;
   232→
   233→  if (newHead.blockRoot !== oldHead.blockRoot) {
   234→    // Set head state as strong reference
   235→    this.regen.updateHeadState(newHead, postState);
   236→
   237→    try {
   238→      this.emitter.emit(routes.events.EventType.head, {
   239→        block: newHead.blockRoot,
   240→        epochTransition: computeStartSlotAtEpoch(computeEpochAtSlot(newHead.slot)) === newHead.slot,
   241→        slot: newHead.slot,
   242→        state: newHead.stateRoot,
   243→        previousDutyDependentRoot: this.forkChoice.getDependentRoot(newHead, EpochDifference.previous),
   244→        currentDutyDependentRoot: this.forkChoice.getDependentRoot(newHead, EpochDifference.current),
   245→        executionOptimistic: isOptimisticBlock(newHead),
   246→      });
   247→    } catch (e) {
   248→      // getDependentRoot() may fail with error: "No block for root" as we can see in holesky non-finality issue
   249→      this.logger.debug("Error emitting head event", {slot: newHead.slot, root: newHead.blockRoot}, e as Error);
   250→    }
   251→
   252→    const delaySec = this.clock.secFromSlot(newHead.slot);
   253→    this.logger.verbose("New chain head", {
   254→      slot: newHead.slot,
   255→      root: newHead.blockRoot,
   256→      delaySec,
   257→    });
   258→
   259→    if (this.metrics) {
   260→      this.metrics.headSlot.set(newHead.slot);
   261→      // Only track "recent" blocks. Otherwise sync can distort this metrics heavily.
   262→      // We want to track recent blocks coming from gossip, unknown block sync, and API.
   263→      if (delaySec < (SLOTS_PER_EPOCH * this.config.SLOT_DURATION_MS) / 1000) {
   264→        this.metrics.importBlock.elapsedTimeTillBecomeHead.observe(delaySec);
   265→        const cutOffSec = this.config.getAttestationDueMs(this.config.getForkName(blockSlot)) / 1000;
   266→        if (delaySec > cutOffSec) {
   267→          this.metrics.importBlock.setHeadAfterCutoff.inc();
   268→        }
   269→      }
   270→    }
   271→
   272→    this.onNewHead(newHead);
   273→
   274→    this.metrics?.forkChoice.changedHead.inc();
   275→
   276→    const ancestorResult = this.forkChoice.getCommonAncestorDepth(oldHead, newHead);
   277→    if (ancestorResult.code === AncestorStatus.CommonAncestor) {
   278→      // CommonAncestor = chain reorg, old head and new head not direct descendants
   279→
   280→      const forkChoiceReorgEventData: ReorgEventData = {
   281→        depth: ancestorResult.depth,
   282→        epoch: computeEpochAtSlot(newHead.slot),
   283→        slot: newHead.slot,
   284→        newHeadBlock: newHead.blockRoot,
   285→        oldHeadBlock: oldHead.blockRoot,
   286→        newHeadState: newHead.stateRoot,
   287→        oldHeadState: oldHead.stateRoot,
   288→        executionOptimistic: isOptimisticBlock(newHead),
   289→      };
   290→
   291→      this.emitter.emit(routes.events.EventType.chainReorg, forkChoiceReorgEventData);
   292→      this.logger.verbose("Chain reorg", forkChoiceReorgEventData);
   293→
   294→      this.metrics?.forkChoice.reorg.inc();
   295→      this.metrics?.forkChoice.reorgDistance.observe(ancestorResult.depth);
   296→    }
   297→
   298→    // Lightclient server support (only after altair)
   299→    // - Persist state witness
   300→    // - Use block's syncAggregate
   301→    if (blockEpoch >= this.config.ALTAIR_FORK_EPOCH) {
   302→      // we want to import block asap so do this in the next event loop
   303→      callInNextEventLoop(() => {
   304→        try {
   305→          this.lightClientServer?.onImportBlockHead(
   306→            block.message as BeaconBlock<ForkPostAltair>,
   307→            postState as CachedBeaconStateAltair,
   308→            parentBlockSlot
   309→          );
   310→        } catch (e) {
   311→          this.logger.verbose("Error lightClientServer.onImportBlock", {slot: blockSlot}, e as Error);
   312→        }
   313→      });
   314→    }
   315→  }
   316→
   317→  // 6. Queue notifyForkchoiceUpdate to engine api
   318→  //
   319→  // NOTE: forkChoice.fsStore.finalizedCheckpoint MUST only change in response to an onBlock event
   320→  // Notifying EL of head and finalized updates as below is usually done within the 1st 4s of the slot.
   321→  // If there is an advanced payload generation in the next slot, we'll notify EL again 4s before next
   322→  // slot via PrepareNextSlotScheduler. There is no harm updating the ELs with same data, it will just ignore it.
   323→
   324→  // Suppress fcu call if shouldOverrideFcu is true. This only happens if we have proposer boost reorg enabled
   325→  // and the block is weak and can potentially be reorged out.
   326→  let shouldOverrideFcu = false;
   327→
   328→  if (blockSlot >= currentSlot && isExecutionStateType(postState)) {
   329→    let notOverrideFcuReason = NotReorgedReason.Unknown;
   330→    const proposalSlot = blockSlot + 1;
   331→    try {
   332→      const proposerIndex = postState.epochCtx.getBeaconProposer(proposalSlot);
   333→      const feeRecipient = this.beaconProposerCache.get(proposerIndex);
   334→
   335→      if (feeRecipient) {
   336→        // We would set this to true if
   337→        //  1) This is a gossip block
   338→        //  2) We are proposer of next slot
   339→        //  3) Proposer boost reorg related flag is turned on (this is checked inside the function)
   340→        //  4) Block meets the criteria of being re-orged out (this is also checked inside the function)
   341→        const result = this.forkChoice.shouldOverrideForkChoiceUpdate(
   342→          blockSummary.blockRoot,
   343→          this.clock.secFromSlot(currentSlot),
   344→          currentSlot
   345→        );
   346→        shouldOverrideFcu = result.shouldOverrideFcu;
   347→        if (!result.shouldOverrideFcu) {
   348→          notOverrideFcuReason = result.reason;
   349→        }
   350→      } else {
   351→        notOverrideFcuReason = NotReorgedReason.NotProposerOfNextSlot;
   352→      }
   353→    } catch (e) {
   354→      if (isStartSlotOfEpoch(proposalSlot)) {
   355→        notOverrideFcuReason = NotReorgedReason.NotShufflingStable;
   356→      } else {
   357→        this.logger.warn("Unable to get beacon proposer. Do not override fcu.", {proposalSlot}, e as Error);
   358→      }
   359→    }
   360→
   361→    if (shouldOverrideFcu) {
   362→      this.logger.verbose("Weak block detected. Skip fcu call in importBlock", {
   363→        blockRoot: blockRootHex,
   364→        slot: blockSlot,
   365→      });
   366→    } else {
   367→      this.metrics?.importBlock.notOverrideFcuReason.inc({reason: notOverrideFcuReason});
   368→      this.logger.verbose("Strong block detected. Not override fcu call", {
   369→        blockRoot: blockRootHex,
   370→        slot: blockSlot,
   371→        reason: notOverrideFcuReason,
   372→      });
   373→    }
   374→  }
   375→
   376→  if (
   377→    !this.opts.disableImportExecutionFcU &&
   378→    (newHead.blockRoot !== oldHead.blockRoot || currFinalizedEpoch !== prevFinalizedEpoch) &&
   379→    !shouldOverrideFcu
   380→  ) {
   381→    /**
   382→     * On post BELLATRIX_EPOCH but pre TTD, blocks include empty execution payload with a zero block hash.
   383→     * The consensus clients must not send notifyForkchoiceUpdate before TTD since the execution client will error.
   384→     * So we must check that:
   385→     * - `headBlockHash !== null` -> Pre BELLATRIX_EPOCH
   386→     * - `headBlockHash !== ZERO_HASH` -> Pre TTD
   387→     */
   388→    const headBlockHash = this.forkChoice.getHead().executionPayloadBlockHash ?? ZERO_HASH_HEX;
   389→    /**
   390→     * After BELLATRIX_EPOCH and TTD it's okay to send a zero hash block hash for the finalized block. This will happen if
   391→     * the current finalized block does not contain any execution payload at all (pre MERGE_EPOCH) or if it contains a
   392→     * zero block hash (pre TTD)
   393→     */
   394→    const safeBlockHash = this.forkChoice.getJustifiedBlock().executionPayloadBlockHash ?? ZERO_HASH_HEX;
   395→    const finalizedBlockHash = this.forkChoice.getFinalizedBlock().executionPayloadBlockHash ?? ZERO_HASH_HEX;
   396→    if (headBlockHash !== ZERO_HASH_HEX) {
   397→      this.executionEngine
   398→        .notifyForkchoiceUpdate(
   399→          this.config.getForkName(this.forkChoice.getHead().slot),
   400→          headBlockHash,
   401→          safeBlockHash,
   402→          finalizedBlockHash
   403→        )
   404→        .catch((e) => {
   405→          if (!isErrorAborted(e) && !isQueueErrorAborted(e)) {
   406→            this.logger.error("Error pushing notifyForkchoiceUpdate()", {headBlockHash, finalizedBlockHash}, e);
   407→          }
   408→        });
   409→    }
   410→  }
   411→
   412→  if (!isStateValidatorsNodesPopulated(postState)) {
   413→    this.logger.verbose("After importBlock caching postState without SSZ cache", {slot: postState.slot});
   414→  }
   415→
   416→  if (blockSlot % SLOTS_PER_EPOCH === 0) {
   417→    // Cache state to preserve epoch transition work
   418→    const checkpointState = postState;
   419→    const cp = getCheckpointFromState(checkpointState);
   420→    this.regen.addCheckpointState(cp, checkpointState);
   421→    // consumers should not mutate or get the transfered cache
   422→    this.emitter.emit(ChainEvent.checkpoint, cp, checkpointState.clone(true));
   423→
   424→    // Note: in-lined code from previos handler of ChainEvent.checkpoint
   425→    this.logger.verbose("Checkpoint processed", toCheckpointHex(cp));
   426→
   427→    const activeValidatorsCount = checkpointState.epochCtx.currentShuffling.activeIndices.length;
   428→    this.metrics?.currentActiveValidators.set(activeValidatorsCount);
   429→    this.metrics?.currentValidators.set({status: "active"}, activeValidatorsCount);
   430→
   431→    const parentBlockSummary = this.forkChoice.getBlock(checkpointState.latestBlockHeader.parentRoot);
   432→
   433→    if (parentBlockSummary) {
   434→      const justifiedCheckpoint = checkpointState.currentJustifiedCheckpoint;
   435→      const justifiedEpoch = justifiedCheckpoint.epoch;
   436→      const preJustifiedEpoch = parentBlockSummary.justifiedEpoch;
   437→      if (justifiedEpoch > preJustifiedEpoch) {
   438→        this.logger.verbose("Checkpoint justified", toCheckpointHex(justifiedCheckpoint));
   439→        this.metrics?.previousJustifiedEpoch.set(checkpointState.previousJustifiedCheckpoint.epoch);
   440→        this.metrics?.currentJustifiedEpoch.set(justifiedCheckpoint.epoch);
   441→      }
   442→      const finalizedCheckpoint = checkpointState.finalizedCheckpoint;
   443→      const finalizedEpoch = finalizedCheckpoint.epoch;
   444→      const preFinalizedEpoch = parentBlockSummary.finalizedEpoch;
   445→      if (finalizedEpoch > preFinalizedEpoch) {
   446→        this.emitter.emit(routes.events.EventType.finalizedCheckpoint, {
   447→          block: toRootHex(finalizedCheckpoint.root),
   448→          epoch: finalizedCheckpoint.epoch,
   449→          state: toRootHex(checkpointState.hashTreeRoot()),
   450→          executionOptimistic: false,
   451→        });
   452→        this.logger.verbose("Checkpoint finalized", toCheckpointHex(finalizedCheckpoint));
   453→        this.metrics?.finalizedEpoch.set(finalizedCheckpoint.epoch);
   454→      }
   455→    }
   456→  }
   457→
   458→  // Send block events, only for recent enough blocks
   459→
   460→  if (currentSlot - blockSlot < EVENTSTREAM_EMIT_RECENT_BLOCK_SLOTS) {
   461→    // We want to import block asap so call all event handler in the next event loop
   462→    callInNextEventLoop(() => {
   463→      // NOTE: Skip emitting if there are no listeners from the API
   464→      if (this.emitter.listenerCount(routes.events.EventType.block)) {
   465→        this.emitter.emit(routes.events.EventType.block, {
   466→          block: blockRootHex,
   467→          slot: blockSlot,
   468→          executionOptimistic: blockSummary != null && isOptimisticBlock(blockSummary),
   469→        });
   470→      }
   471→      if (this.emitter.listenerCount(routes.events.EventType.voluntaryExit)) {
   472→        for (const voluntaryExit of block.message.body.voluntaryExits) {
   473→          this.emitter.emit(routes.events.EventType.voluntaryExit, voluntaryExit);
   474→        }
   475→      }
   476→      if (this.emitter.listenerCount(routes.events.EventType.blsToExecutionChange)) {
   477→        for (const blsToExecutionChange of (block.message as capella.BeaconBlock).body.blsToExecutionChanges ?? []) {
   478→          this.emitter.emit(routes.events.EventType.blsToExecutionChange, blsToExecutionChange);
   479→        }
   480→      }
   481→      if (this.emitter.listenerCount(routes.events.EventType.attestation)) {
   482→        for (const attestation of block.message.body.attestations) {
   483→          this.emitter.emit(routes.events.EventType.attestation, attestation);
   484→        }
   485→      }
   486→      if (this.emitter.listenerCount(routes.events.EventType.attesterSlashing)) {
   487→        for (const attesterSlashing of block.message.body.attesterSlashings) {
   488→          this.emitter.emit(routes.events.EventType.attesterSlashing, attesterSlashing);
   489→        }
   490→      }
   491→      if (this.emitter.listenerCount(routes.events.EventType.proposerSlashing)) {
   492→        for (const proposerSlashing of block.message.body.proposerSlashings) {
   493→          this.emitter.emit(routes.events.EventType.proposerSlashing, proposerSlashing);
   494→        }
   495→      }
   496→    });
   497→  }
   498→
   499→  // Register stat metrics about the block after importing it
   500→  this.metrics?.parentBlockDistance.observe(blockSlot - parentBlockSlot);
   501→  this.metrics?.proposerBalanceDeltaAny.observe(fullyVerifiedBlock.proposerBalanceDelta);
   502→  this.validatorMonitor?.registerImportedBlock(block.message, fullyVerifiedBlock);
   503→  if (this.config.getForkSeq(blockSlot) >= ForkSeq.altair) {
   504→    this.validatorMonitor?.registerSyncAggregateInBlock(
   505→      blockEpoch,
   506→      (block as altair.SignedBeaconBlock).message.body.syncAggregate,
   507→      fullyVerifiedBlock.postState.epochCtx.currentSyncCommitteeIndexed.validatorIndices
   508→    );
   509→  }
   510→
   511→  if (isBlockInputColumns(blockInput)) {
   512→    for (const {source} of blockInput.getSampledColumnsWithSource()) {
   513→      this.metrics?.importBlock.columnsBySource.inc({source});
   514→    }
   515→  } else if (isBlockInputBlobs(blockInput)) {
   516→    for (const {source} of blockInput.getAllBlobsWithSource()) {
   517→      this.metrics?.importBlock.blobsBySource.inc({blobsSource: source});
   518→    }
   519→  }
   520→
   521→  const advancedSlot = this.clock.slotWithFutureTolerance(REPROCESS_MIN_TIME_TO_NEXT_SLOT_SEC);
   522→
   523→  // Gossip blocks need to be imported as soon as possible, waiting attestations could be processed
   524→  // in the next event loop. See https://github.com/ChainSafe/lodestar/issues/4789
   525→  callInNextEventLoop(() => {
   526→    this.reprocessController.onBlockImported({slot: blockSlot, root: blockRootHex}, advancedSlot);
   527→  });
   528→
   529→  if (opts.seenTimestampSec !== undefined) {
   530→    const recvToValidation = Date.now() / 1000 - opts.seenTimestampSec;
   531→    const validationTime = recvToValidation - recvToValLatency;
   532→
   533→    this.metrics?.gossipBlock.blockImport.recvToValidation.observe(recvToValidation);
   534→    this.metrics?.gossipBlock.blockImport.validationTime.observe(validationTime);
   535→
   536→    this.logger.debug("Imported block", {slot: blockSlot, recvToValLatency, recvToValidation, validationTime});
   537→  }
   538→
   539→  this.logger.verbose("Block processed", {
   540→    slot: blockSlot,
   541→    root: blockRootHex,
   542→    delaySec: this.clock.secFromSlot(blockSlot),
   543→  });
   544→}
   545→
   546→export function addAttestationPreElectra(
   547→  this: BeaconChain,
   548→  // added to have the same signature as addAttestationPostElectra
   549→  _: EpochCache,
   550→  target: phase0.Checkpoint,
   551→  attDataRoot: string,
   552→  attestation: Attestation,
   553→  indexedAttestation: phase0.IndexedAttestation
   554→): void {
   555→  this.seenAggregatedAttestations.add(
   556→    target.epoch,
   557→    attestation.data.index,
   558→    attDataRoot,
   559→    {aggregationBits: attestation.aggregationBits, trueBitCount: indexedAttestation.attestingIndices.length},
   560→    true
   561→  );
   562→}
   563→
   564→export function addAttestationPostElectra(
   565→  this: BeaconChain,
   566→  epochCtx: EpochCache,
   567→  target: phase0.Checkpoint,
   568→  attDataRoot: string,
   569→  attestation: Attestation<ForkPostElectra>,
   570→  indexedAttestation: electra.IndexedAttestation
   571→): void {
   572→  const committeeIndices = attestation.committeeBits.getTrueBitIndexes();
   573→  if (committeeIndices.length === 1) {
   574→    this.seenAggregatedAttestations.add(
   575→      target.epoch,
   576→      committeeIndices[0],
   577→      attDataRoot,
   578→      {aggregationBits: attestation.aggregationBits, trueBitCount: indexedAttestation.attestingIndices.length},
   579→      true
   580→    );
   581→  } else {
   582→    const committees = epochCtx.getBeaconCommittees(attestation.data.slot, committeeIndices);
   583→    const aggregationBools = attestation.aggregationBits.toBoolArray();
   584→    let offset = 0;
   585→    for (let i = 0; i < committees.length; i++) {
   586→      const committee = committees[i];
   587→      const aggregationBits = BitArray.fromBoolArray(aggregationBools.slice(offset, offset + committee.length));
   588→      const trueBitCount = aggregationBits.getTrueBitIndexes().length;
   589→      offset += committee.length;
   590→      this.seenAggregatedAttestations.add(
   591→        target.epoch,
   592→        committeeIndices[i],
   593→        attDataRoot,
   594→        {aggregationBits, trueBitCount},
   595→        true
   596→      );
   597→    }
   598→  }
   599→}
