     9→import {IBeaconDb} from "../../../db/index.js";
    10→import {BlockArchiveBatchPutBinaryItem} from "../../../db/repositories/index.js";
    11→import {ensureDir, writeIfNotExist} from "../../../util/file.js";
    12→import {BlockRootHex} from "../../../util/sszBytes.js";
    13→import {LightClientServer} from "../../lightClient/index.js";
    14→
    15→// Process in chunks to avoid OOM
    16→// this number of blocks per chunk is tested in e2e test blockArchive.test.ts
    17→// TODO: Review after merge since the size of blocks will increase significantly
    18→const BLOCK_BATCH_SIZE = 256;
    19→const BLOB_SIDECAR_BATCH_SIZE = 32;
    20→
    21→type BlockRootSlot = {slot: Slot; root: Uint8Array};
    22→type CheckpointHex = {epoch: Epoch; rootHex: RootHex};
    23→
    24→/**
    25→ * Persist orphaned block to disk
    26→ */
    27→async function persistOrphanedBlock(
    28→  slot: Slot,
    29→  blockRoot: BlockRootHex,
    30→  bytes: Uint8Array,
    31→  opts: {
    32→    persistOrphanedBlocksDir: string;
    33→  }
    34→) {
    35→  const dirpath = path.join(opts.persistOrphanedBlocksDir ?? "orphaned_blocks");
    36→  const filepath = path.join(dirpath, `${slot}_${blockRoot}.ssz`);
    37→  await ensureDir(dirpath);
    38→  await writeIfNotExist(filepath, bytes);
    39→}
    40→
    41→/**
    42→ * Archives finalized blocks from active bucket to archive bucket.
    43→ *
    44→ * Only archive blocks on the same chain to the finalized checkpoint.
    45→ * Each run should move all finalized blocks to blockArhive db to make it consistent
    46→ * to stateArchive, so that the node always work well when we restart.
    47→ * Note that the finalized block still stay in forkchoice to check finalize checkpoint of next onBlock calls,
    48→ * the next run should not reprocess finalzied block of this run.
    49→ */
    50→export async function archiveBlocks(
    51→  config: ChainForkConfig,
    52→  db: IBeaconDb,
    53→  forkChoice: IForkChoice,
    54→  lightclientServer: LightClientServer | undefined,
    55→  logger: Logger,
    56→  finalizedCheckpoint: CheckpointHex,
    57→  currentEpoch: Epoch,
    58→  archiveDataEpochs?: number,
    59→  persistOrphanedBlocks?: boolean,
    60→  persistOrphanedBlocksDir?: string
    61→): Promise<void> {
    62→  // Use fork choice to determine the blocks to archive and delete
    63→  // getAllAncestorBlocks response includes the finalized block, so it's also moved to the cold db
    64→  const {ancestors: finalizedCanonicalBlocks, nonAncestors: finalizedNonCanonicalBlocks} =
    65→    forkChoice.getAllAncestorAndNonAncestorBlocks(finalizedCheckpoint.rootHex);
    66→
    67→  // NOTE: The finalized block will be exactly the first block of `epoch` or previous
    68→  const finalizedPostDeneb = finalizedCheckpoint.epoch >= config.DENEB_FORK_EPOCH;
    69→  const finalizedPostFulu = finalizedCheckpoint.epoch >= config.FULU_FORK_EPOCH;
    70→
    71→  const finalizedCanonicalBlockRoots: BlockRootSlot[] = finalizedCanonicalBlocks.map((block) => ({
    72→    slot: block.slot,
    73→    root: fromHex(block.blockRoot),
    74→  }));
    75→
    76→  if (finalizedCanonicalBlockRoots.length > 0) {
    77→    await migrateBlocksFromHotToColdDb(db, finalizedCanonicalBlockRoots);
    78→    logger.verbose("Migrated blocks from hot DB to cold DB", {
    79→      fromSlot: finalizedCanonicalBlockRoots[0].slot,
    80→      toSlot: finalizedCanonicalBlockRoots.at(-1)?.slot,
    81→      size: finalizedCanonicalBlockRoots.length,
    82→    });
    83→
    84→    if (finalizedPostDeneb) {
    85→      const migratedEntries = await migrateBlobSidecarsFromHotToColdDb(
    86→        config,
    87→        db,
    88→        finalizedCanonicalBlockRoots,
    89→        currentEpoch
    90→      );
    91→      logger.verbose("Migrated blobSidecars from hot DB to cold DB", {migratedEntries});
    92→    }
    93→
    94→    if (finalizedPostFulu) {
    95→      const migratedEntries = await migrateDataColumnSidecarsFromHotToColdDb(
    96→        config,
    97→        db,
    98→        logger,
    99→        finalizedCanonicalBlockRoots,
   100→        currentEpoch
   101→      );
   102→      logger.verbose("Migrated dataColumnSidecars from hot DB to cold DB", {migratedEntries});
   103→    }
   104→  }
   105→
   106→  // deleteNonCanonicalBlocks
   107→  // loop through forkchoice single time
   108→
   109→  const nonCanonicalBlockRoots = finalizedNonCanonicalBlocks.map((summary) => fromHex(summary.blockRoot));
   110→  if (nonCanonicalBlockRoots.length > 0) {
   111→    if (persistOrphanedBlocks) {
   112→      // Persist orphaned blocks to disk before deleting them from hot db
   113→      await Promise.all(
   114→        nonCanonicalBlockRoots.map(async (root, index) => {
   115→          const block = finalizedNonCanonicalBlocks[index];
   116→          const blockBytes = await db.block.getBinary(root);
   117→          const logCtx = {slot: block.slot, root: block.blockRoot};
   118→          if (blockBytes) {
   119→            await persistOrphanedBlock(block.slot, block.blockRoot, blockBytes, {
   120→              persistOrphanedBlocksDir: persistOrphanedBlocksDir ?? "orphaned_blocks",
   121→            });
   122→            logger.verbose("Persisted orphaned block", logCtx);
   123→          } else {
   124→            logger.warn("Tried to persist orphaned block but no block found", logCtx);
   125→          }
   126→        })
   127→      );
   128→    }
   129→
   130→    await db.block.batchDelete(nonCanonicalBlockRoots);
   131→    logger.verbose("Deleted non canonical blocks from hot DB", {
   132→      slots: finalizedNonCanonicalBlocks.map((summary) => summary.slot).join(","),
   133→    });
   134→
   135→    if (finalizedPostDeneb) {
   136→      await db.blobSidecars.batchDelete(nonCanonicalBlockRoots);
   137→      logger.verbose("Deleted non canonical blobSidecars from hot DB");
   138→    }
   139→
   140→    if (finalizedPostFulu) {
   141→      await db.dataColumnSidecar.deleteMany(nonCanonicalBlockRoots);
   142→      logger.verbose("Deleted non canonical dataColumnSidecars from hot DB");
   143→    }
   144→  }
   145→
   146→  // Delete expired blobs
   147→  // Keep only `[current_epoch - max(MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS, archiveDataEpochs)]`
   148→  // if archiveDataEpochs set to Infinity do not prune`
   149→  if (finalizedPostDeneb) {
   150→    if (archiveDataEpochs !== Infinity) {
   151→      const blobsArchiveWindow = Math.max(config.MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS, archiveDataEpochs ?? 0);
   152→      const blobSidecarsMinEpoch = currentEpoch - blobsArchiveWindow;
   153→      if (blobSidecarsMinEpoch >= config.DENEB_FORK_EPOCH) {
   154→        const slotsToDelete = await db.blobSidecarsArchive.keys({lt: computeStartSlotAtEpoch(blobSidecarsMinEpoch)});
   155→        if (slotsToDelete.length > 0) {
   156→          await db.blobSidecarsArchive.batchDelete(slotsToDelete);
   157→          logger.verbose(`blobSidecars prune: batchDelete range ${slotsToDelete[0]}..${slotsToDelete.at(-1)}`);
   158→        } else {
   159→          logger.verbose(`blobSidecars prune: no entries before epoch ${blobSidecarsMinEpoch}`);
   160→        }
   161→      }
   162→    } else {
   163→      logger.verbose("blobSidecars pruning skipped: archiveDataEpochs set to Infinity");
   164→    }
   165→  }
   166→
   167→  // Delete expired data column sidecars
   168→  // Keep only `[current_epoch - max(MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS, archiveDataEpochs)]`
   169→  if (finalizedPostFulu) {
   170→    if (archiveDataEpochs !== Infinity) {
   171→      const dataColumnSidecarsArchiveWindow = Math.max(
   172→        config.MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS,
   173→        archiveDataEpochs ?? 0
   174→      );
   175→      const dataColumnSidecarsMinEpoch = currentEpoch - dataColumnSidecarsArchiveWindow;
   176→      if (dataColumnSidecarsMinEpoch >= config.FULU_FORK_EPOCH) {
   177→        const prefixedKeys = await db.dataColumnSidecarArchive.keys({
   178→          // The `id` value `0` refers to the column index. So we want to fetch all sidecars less than zero column of `dataColumnSidecarsMinEpoch`
   179→          lt: {prefix: computeStartSlotAtEpoch(dataColumnSidecarsMinEpoch), id: 0},
   180→        });
   181→        // for each slot there could be multiple dataColumnSidecar, so we need to deduplicate it
   182→        const slotsToDelete = [...new Set(prefixedKeys.map(({prefix}) => prefix))].sort((a, b) => a - b);
   183→
   184→        if (slotsToDelete.length > 0) {
   185→          await db.dataColumnSidecarArchive.deleteMany(slotsToDelete);
   186→          logger.verbose("dataColumnSidecars prune", {
   187→            slotRange: prettyPrintIndices(slotsToDelete),
   188→            numOfSlots: slotsToDelete.length,
   189→            totalNumOfSidecars: prefixedKeys.length,
   190→          });
   191→        } else {
   192→          logger.verbose(`dataColumnSidecars prune: no entries before epoch ${dataColumnSidecarsMinEpoch}`);
   193→        }
   194→      } else {
   195→        logger.verbose(
   196→          `dataColumnSidecars pruning skipped: ${dataColumnSidecarsMinEpoch} is before fulu fork epoch ${config.FULU_FORK_EPOCH}`
   197→        );
   198→      }
   199→    } else {
   200→      logger.verbose("dataColumnSidecars pruning skipped: archiveDataEpochs set to Infinity");
   201→    }
   202→  }
   203→
   204→  // Prunning potential checkpoint data
   205→  const finalizedCanonicalNonCheckpointBlocks = getNonCheckpointBlocks(finalizedCanonicalBlockRoots);
   206→  const nonCheckpointBlockRoots: Uint8Array[] = [...nonCanonicalBlockRoots];
   207→  for (const block of finalizedCanonicalNonCheckpointBlocks) {
   208→    nonCheckpointBlockRoots.push(block.root);
   209→  }
   210→
   211→  if (lightclientServer) {
   212→    await lightclientServer.pruneNonCheckpointData(nonCheckpointBlockRoots);
   213→  }
   214→
   215→  logger.verbose("Archiving of finalized blocks complete", {
   216→    totalArchived: finalizedCanonicalBlocks.length,
   217→    finalizedEpoch: finalizedCheckpoint.epoch,
   218→  });
   219→}
   220→
   221→async function migrateBlocksFromHotToColdDb(db: IBeaconDb, blocks: BlockRootSlot[]): Promise<void> {
   222→  // Start from `i=0`: 1st block in iterateAncestorBlocks() is the finalized block itself
   223→  // we move it to blockArchive but forkchoice still have it to check next onBlock calls
   224→  // the next iterateAncestorBlocks call does not return this block
   225→  for (let i = 0; i < blocks.length; i += BLOCK_BATCH_SIZE) {
   226→    const toIdx = Math.min(i + BLOCK_BATCH_SIZE, blocks.length);
   227→    const canonicalBlocks = blocks.slice(i, toIdx);
   228→
   229→    // processCanonicalBlocks
   230→    if (canonicalBlocks.length === 0) return;
   231→
   232→    // load Buffer instead of SignedBeaconBlock to improve performance
   233→    const canonicalBlockEntries: BlockArchiveBatchPutBinaryItem[] = await Promise.all(
   234→      canonicalBlocks.map(async (block) => {
   235→        const blockBuffer = await db.block.getBinary(block.root);
   236→        if (!blockBuffer) {
   237→          throw Error(`Block not found for slot ${block.slot} root ${toRootHex(block.root)}`);
   238→        }
   239→        return {
   240→          key: block.slot,
   241→          value: blockBuffer,
   242→          slot: block.slot,
   243→          blockRoot: block.root,
   244→          // TODO: Benchmark if faster to slice Buffer or fromHex()
   245→          parentRoot: getParentRootFromSignedBlock(blockBuffer),
   246→        };
   247→      })
   248→    );
   249→
   250→    // put to blockArchive db and delete block db
   251→    await Promise.all([
   252→      db.blockArchive.batchPutBinary(canonicalBlockEntries),
   253→      db.block.batchDelete(canonicalBlocks.map((block) => block.root)),
   254→    ]);
   255→  }
   256→}
   257→
   258→/**
   259→ * Migrate blobSidecars from hot db to cold db.
   260→ * @returns true if we do that, false if block is out of range data.
   261→ */
   262→async function migrateBlobSidecarsFromHotToColdDb(
   263→  config: ChainForkConfig,
   264→  db: IBeaconDb,
   265→  blocks: BlockRootSlot[],
   266→  currentEpoch: Epoch
   267→): Promise<number> {
   268→  let migratedWrappedBlobSidecars = 0;
   269→  for (let i = 0; i < blocks.length; i += BLOB_SIDECAR_BATCH_SIZE) {
   270→    const toIdx = Math.min(i + BLOB_SIDECAR_BATCH_SIZE, blocks.length);
   271→    const canonicalBlocks = blocks.slice(i, toIdx);
   272→
   273→    // processCanonicalBlocks
   274→    if (canonicalBlocks.length === 0) break;
   275→
   276→    // load Buffer instead of ssz deserialized to improve performance
   277→    const canonicalBlobSidecarsEntries: KeyValue<Slot, Uint8Array>[] = await Promise.all(
   278→      canonicalBlocks
   279→        .filter((block) => {
   280→          const blockSlot = block.slot;
   281→          const blockEpoch = computeEpochAtSlot(blockSlot);
   282→          const forkSeq = config.getForkSeq(blockSlot);
   283→          return (
   284→            forkSeq >= ForkSeq.deneb &&
   285→            forkSeq < ForkSeq.fulu &&
   286→            // if block is out of ${config.MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS}, skip this step
   287→            blockEpoch >= currentEpoch - config.MIN_EPOCHS_FOR_BLOB_SIDECARS_REQUESTS
   288→          );
   289→        })
   290→        .map(async (block) => {
   291→          const bytes = await db.blobSidecars.getBinary(block.root);
   292→          if (!bytes) {
   293→            throw Error(`No blobSidecars found for slot ${block.slot} root ${toRootHex(block.root)}`);
   294→          }
   295→          return {key: block.slot, value: bytes};
   296→        })
   297→    );
   298→
   299→    // put to blockArchive db and delete block db
   300→    await Promise.all([
   301→      db.blobSidecarsArchive.batchPutBinary(canonicalBlobSidecarsEntries),
   302→      db.blobSidecars.batchDelete(canonicalBlocks.map((block) => block.root)),
   303→    ]);
   304→    migratedWrappedBlobSidecars += canonicalBlobSidecarsEntries.length;
   305→  }
   306→
   307→  return migratedWrappedBlobSidecars;
   308→}
   309→
   310→// TODO: This function can be simplified further by reducing layers of promises in a loop
   311→async function migrateDataColumnSidecarsFromHotToColdDb(
   312→  config: ChainForkConfig,
   313→  db: IBeaconDb,
   314→  logger: Logger,
   315→  blocks: BlockRootSlot[],
   316→  currentEpoch: Epoch
   317→): Promise<number> {
   318→  let migratedWrappedDataColumns = 0;
   319→  for (let i = 0; i < blocks.length; i += BLOB_SIDECAR_BATCH_SIZE) {
   320→    const toIdx = Math.min(i + BLOB_SIDECAR_BATCH_SIZE, blocks.length);
   321→    const canonicalBlocks = blocks.slice(i, toIdx);
   322→
   323→    // processCanonicalBlocks
   324→    if (canonicalBlocks.length === 0) break;
   325→    const promises = [];
   326→
   327→    // load Buffer instead of ssz deserialized to improve performance
   328→    for (const block of canonicalBlocks) {
   329→      const blockSlot = block.slot;
   330→      const blockEpoch = computeEpochAtSlot(blockSlot);
   331→
   332→      if (
   333→        config.getForkSeq(blockSlot) < ForkSeq.fulu ||
   334→        // if block is out of ${config.MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS}, skip this step
   335→        blockEpoch < currentEpoch - config.MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS
   336→      ) {
   337→        continue;
   338→      }
   339→
   340→      const dataColumnSidecarBytes = await fromAsync(db.dataColumnSidecar.valuesStreamBinary(block.root));
   341→      // there could be 0 dataColumnSidecarBytes if block has no blob
   342→      logger.verbose("migrateDataColumnSidecarsFromHotToColdDb", {
   343→        slot: block.slot,
   344→        root: toRootHex(block.root),
   345→        numSidecars: dataColumnSidecarBytes.length,
   346→      });
   347→      promises.push(
   348→        db.dataColumnSidecarArchive.putManyBinary(
   349→          block.slot,
   350→          dataColumnSidecarBytes.map((p) => ({key: p.id, value: p.value}))
   351→        )
   352→      );
   353→      migratedWrappedDataColumns += dataColumnSidecarBytes.length;
   354→    }
   355→
   356→    promises.push(db.dataColumnSidecar.deleteMany(canonicalBlocks.map((block) => block.root)));
   357→
   358→    // put to blockArchive db and delete block db
   359→    await Promise.all(promises);
   360→  }
   361→
   362→  return migratedWrappedDataColumns;
   363→}
   364→
   365→/**
   366→ * ```
   367→ * class SignedBeaconBlock(Container):
   368→ *   message: BeaconBlock [offset - 4 bytes]
   369→ *   signature: BLSSignature [fixed - 96 bytes]
   370→ *
   371→ * class BeaconBlock(Container):
   372→ *   slot: Slot [fixed - 8 bytes]
   373→ *   proposer_index: ValidatorIndex [fixed - 8 bytes]
   374→ *   parent_root: Root [fixed - 32 bytes]
   375→ *   state_root: Root
   376→ *   body: BeaconBlockBody
   377→ * ```
   378→ * From byte: `4 + 96 + 8 + 8 = 116`
   379→ * To byte: `116 + 32 = 148`
   380→ */
   381→export function getParentRootFromSignedBlock(bytes: Uint8Array): Uint8Array {
   382→  return bytes.slice(116, 148);
   383→}
   384→
   385→/**
   386→ *
   387→ * @param blocks sequence of linear blocks, from child to ancestor.
   388→ * In ProtoArray.getAllAncestorNodes child nodes are pushed first to the returned array.
   389→ */
   390→export function getNonCheckpointBlocks<T extends {slot: Slot}>(blocks: T[]): T[] {
   391→  // Iterate from lowest child to highest ancestor
   392→  // Look for the checkpoint of the lowest epoch
   393→  // If block at `epoch * SLOTS_PER_EPOCH`, it's a checkpoint.
   394→  // - Then for the previous epoch all blocks but the 0 are NOT checkpoints
   395→  // - Otherwise for the previous epoch the last block is a checkpoint
   396→
   397→  if (blocks.length < 1) {
   398→    return [];
   399→  }
   400→
   401→  const nonCheckpointBlocks: T[] = [];
   402→  // Start with Infinity to always trigger `blockEpoch < epochPtr` in the first loop
   403→  let epochPtr = Infinity;
   404→  // Assume worst case, since it's unknown if a future epoch will skip the first slot or not.
   405→  // This function must return only blocks that are guaranteed to never become checkpoints.
   406→  let epochPtrHasFirstSlot = false;
   407→
   408→  // blocks order: from child to ancestor, decreasing slot
   409→  for (let i = 0; i < blocks.length; i++) {
   410→    let isCheckpoint = false;
   411→    const block = blocks[i];
   412→    const blockEpoch = computeEpochAtSlot(block.slot);
   413→
   414→    if (blockEpoch < epochPtr) {
   415→      // If future epoch has skipped the first slot, the last block in the previous epoch is a checkpoint
   416→      if (!epochPtrHasFirstSlot) {
   417→        isCheckpoint = true;
   418→      }
   419→
   420→      // Reset epoch pointer
   421→      epochPtr = blockEpoch;
   422→      epochPtrHasFirstSlot = false;
